using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Diagnostics;using System.Windows.Forms;using System.Xml;using Frociart;
internal static class TurtleUiTests {
 const BindingFlags Flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static int checks;static string root;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);checks++;Console.WriteLine("PASS "+why);}
 static T Field<T>(object owner,string name){return(T)owner.GetType().GetField(name,Flags).GetValue(owner);}static object Call(object owner,string name,params object[] args){return owner.GetType().GetMethod(name,Flags).Invoke(owner,args);}
 static void Pump(int ms=90){var watch=Stopwatch.StartNew();do{Application.DoEvents();Thread.Sleep(2);}while(watch.ElapsedMilliseconds<ms);}
 static void Show(Form f){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-3000);f.Show();Pump();}
 static IEnumerable<Control> Desc(Control c){foreach(Control child in c.Controls){yield return child;foreach(var other in Desc(child))yield return other;}}
 static void Shot(Form f,string name){using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,name+".png"));}}
 static void Editors(){foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);
  using(var d=new TurtleEditorDialog(NodeKind.TurtleTurn,"SINISTRA 45",null)){Show(d);Check(d.Direction.SelectedIndex==1&&d.Value.Text=="45","Turn decodes angle and direction");d.Direction.SelectedIndex=0;d.Value.Text="angolo + 5";d.Apply.PerformClick();Check(d.Result=="DESTRA angolo + 5","Turn preserves expression");}
  using(var d=new TurtleEditorDialog(NodeKind.TurtleForward,"SENZA_TRACCIA 25",null)){Show(d);Check(!d.Draw.Checked&&d.Value.Text=="25","Move preserves pen-up setting");d.Draw.Checked=true;d.Value.Text="(";d.Apply.PerformClick();Check(d.Visible&&d.Result==null&&d.Error.Text.Length>0&&d.Value.Text=="(","Bad expression keeps edit recoverable");d.Value.Text="100";d.Size=d.MinimumSize;Shot(d,dark?"forward-dark":"forward-light");d.Apply.PerformClick();Check(d.Result=="100","Valid corrected distance applies");}
  using(var d=new TurtleEditorDialog(NodeKind.TurtlePen,"\"#c0f\"",null)){Show(d);Check(d.Value.Text=="\"#c0f\"","Hex color preserved");d.ColorChoice.SelectedIndex=4;Check(d.Value.Text=="\"rosso\"","Named color selection fills real expression");d.Value.Text="colore";d.Apply.PerformClick();Check(d.Result=="colore","Color can be supplied by a variable");}
  foreach(NodeKind k in new[]{NodeKind.TurtleHome,NodeKind.TurtleClear})using(var d=new TurtleEditorDialog(k,FlowTurtle.DefaultText(k),null)){Show(d);Check(!Desc(d).OfType<TextBox>().Any(t=>t.Visible),"No fake parameter for "+k);d.Apply.PerformClick();Check(d.Result==FlowTurtle.DefaultText(k),"Applies "+k);}
 }
 using(var d=new TurtleEditorDialog(NodeKind.TurtleTurn,"BROKEN keep",null)){Show(d);Check(d.Value.Text=="BROKEN keep"&&d.Error.Text.Length>0,"Malformed draft not dropped");d.Close();Check(d.Result==null,"Cancel leaves original untouched");}
 }
 static void RenderAndExport(){var r=new Interpreter(Examples.TurtleSquare());for(int i=0;i<100&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++)r.Step();Check(r.State==RuntimeState.Completed&&r.Turtle.Segments.Count==4,"Editable square example executes");var snap=r.Turtle.Capture();using(var bitmap=TurtleView.Render(snap,400,400)){bitmap.Save(Path.Combine(root,"square.png"));Check(bitmap.GetPixel(27,200).B>200&&bitmap.GetPixel(27,200).R<80,"PNG has blue square at correct coordinates");Check(bitmap.GetPixel(200,200).ToArgb()==Color.White.ToArgb(),"PNG has neutral paper and no filled square");}
 string svg=FlowTurtle.Svg(snap);File.WriteAllText(Path.Combine(root,"square.svg"),svg);var xml=new XmlDocument();xml.XmlResolver=null;xml.LoadXml(svg);Check(xml.GetElementsByTagName("line").Count==4,"SVG contains all four segments");Check(xml.GetElementsByTagName("line")[0].Attributes["y2"].Value=="-100","SVG maps upward world motion correctly");r.Reset();Check(snap.Segments.Count==4,"Export snapshot independent of restart");
 var dense=new FlowTurtle();var f=FlowTurtle.Parse(NodeKind.TurtleForward,"1");var t=FlowTurtle.Parse(NodeKind.TurtleTurn,"DESTRA 137");for(int i=0;i<10000;i++){dense.Apply(f,1d);dense.Apply(t,137d);}var times=new List<double>();using(var image=new Bitmap(640,480))using(var g=Graphics.FromImage(image)){for(int i=0;i<40;i++){var watch=Stopwatch.StartNew();TurtleView.Draw(g,image.Size,dense.Segments,dense.X,dense.Y,dense.X,dense.Y,dense.Heading,1,1,0,0,true);times.Add(watch.Elapsed.TotalMilliseconds);}}times.Sort();using(var view=new TurtleView{Size=new Size(640,480)}){view.CreateControl();view.Bind(dense);using(var image=new Bitmap(640,480)){view.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));var cached=new List<double>();for(int i=0;i<40;i++){var watch=Stopwatch.StartNew();view.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));cached.Add(watch.Elapsed.TotalMilliseconds);}cached.Sort();File.WriteAllText(Path.Combine(root,"cached-performance.txt"),"10k segments cached median_ms="+cached[20]+" p95_ms="+cached[38]);Console.WriteLine("Cached median "+cached[20]+" p95 "+cached[38]);Check(cached[20]<times[20]/2,"Cached paint is at least twice as fast as full redraw in same process");}}string metric="10k segments GDI median_ms="+times[20]+" p95_ms="+times[38];File.WriteAllText(Path.Combine(root,"render-performance.txt"),metric);Console.WriteLine(metric);
 }
 static void CachedState(){using(var host=new Form{ClientSize=new Size(400,400)})using(var view=new TurtleView{Dock=DockStyle.Fill}){host.Controls.Add(view);Show(host);var red=new FlowTurtle();var blue=new FlowTurtle();var pen=FlowTurtle.Parse(NodeKind.TurtlePen,"\"blu\"");var forward=FlowTurtle.Parse(NodeKind.TurtleForward,"100");red.Apply(pen,"rosso");red.Apply(forward,100d);blue.Apply(pen,"blu");blue.Apply(forward,100d);Check(red.Revision==blue.Revision,"Replacement fixture has same revision");using(var image=new Bitmap(400,400)){view.Bind(red);Pump(400);view.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));Check(image.GetPixel(200,100).R>200&&image.GetPixel(200,100).B<80,"First drawing is red");view.Bind(blue);Pump(400);view.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));Check(image.GetPixel(200,100).B>200&&image.GetPixel(200,100).R<80,"New runner with equal revision invalidates old cached image");blue.Apply(FlowTurtle.Parse(NodeKind.TurtleClear,"Pulisci"),null);view.Bind(blue);Check(Field<Bitmap>(view,"clearGhost")!=null,"Clear captures a fading drawing");Pump(400);view.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));Check(Field<Bitmap>(view,"clearGhost")==null&&image.GetPixel(200,100).ToArgb()==Color.White.ToArgb(),"Clear fade settles and releases its bitmap");}}string path=Path.Combine(root,"atomic.svg");File.WriteAllText(path,"original");bool failed=false;try{DiagramExport.WriteAtomically(path,temp=>{File.WriteAllText(temp,"partial");throw new IOException("injected failure");});}catch(IOException){failed=true;}Check(failed&&File.ReadAllText(path)=="original","Failed export preserves original destination");Check(!Directory.GetFiles(root,".frociart-export-*.tmp").Any(),"Failed export cleans only its temporary file");}
 static void MainUi(MainForm f){f.SetDocument(new Diagram(),null,false);f.EnterEditor();Pump();var group=Desc(f).OfType<FlowButton>().Single(b=>b.Name=="TurtlePaletteGroup");group.PerformClick();Pump();foreach(NodeKind k in FlowTurtle.Kinds){var button=Desc(f).OfType<BlockButton>().Single(b=>b.Name=="TurtlePalette"+k);int count=f.Document.Nodes.Count;Call(button,"OnClick",EventArgs.Empty);Pump();Check(f.Document.Nodes.Count==count+1&&f.Document.Nodes.Last().Kind==k,"Palette creates "+k);Compiler.Block(f.Document.Nodes.Last());}
 using(var picker=new BlockPicker()){var turtle=picker.Items.OfType<ToolStripMenuItem>().Single(i=>i.Name=="TurtleBlockGroup");Check(turtle.DropDownItems.Count==5,"Connection picker contains all turtle actions");foreach(ToolStripItem item in turtle.DropDownItems){NodeKind? selected=null;EventHandler<BlockKindEventArgs> handler=(s,e)=>selected=e.Kind;picker.KindSelected+=handler;item.PerformClick();picker.KindSelected-=handler;Check(selected==(NodeKind)item.Tag,"Picker dispatches "+item.Tag);}}
 f.SetDocument(Examples.TurtleSquare(),null,false);f.EnterEditor();f.SingleStep();Pump();var tabs=Field<SidebarTabs>(f,"tabs");tabs.SelectedTab=Field<Panel>(f,"runTab");Pump();Check(Field<RuntimeSurface>(f,"turtleCard").Visible,"Actual execution panel exposes drawing");for(int i=0;i<40&&f.Runner.State!=RuntimeState.Completed&&f.Runner.State!=RuntimeState.Error;i++)f.Runner.Step();Call(f,"RefreshRuntime");Pump(450);Check(f.Runner.Turtle.Segments.Count==4,"Drawing panel connected to actual runner");Call(f,"ShowTurtle");Pump(450);var large=Field<Form>(f,"turtleWindow");Check(large!=null&&large.Visible,"Expanded drawing opens");Shot(large,"expanded-square");var view=Field<TurtleView>(f,"turtleLarge");var zoom=Field<MotionValue>(view,"zoomMotion");view.Zoom(2);Pump(70);Console.WriteLine("Zoom probe enabled="+UiMotion.Enabled+" value="+zoom.Value+" running="+zoom.Running);Check(zoom.Value>1&&zoom.Value<2.1&&Math.Abs(zoom.Value-2)>.0001&&zoom.Running,"Zoom has an intermediate animated state");Pump(400);Check(Math.Abs(zoom.Value-2)<.001&&!zoom.Running,"Zoom settles without idle timer");view.Fit();Pump(450);Check(Math.Abs(zoom.Value-1)<.001,"Fit restores complete drawing");large.Close();f.SetDocument(FlowPseudocode.Decode("AVANZA 10\nLEGGI lunghezza\nAVANZA lunghezza"),null,false);f.SingleStep();Call(f,"ShowTurtle");for(int i=0;i<10&&f.Runner.State!=RuntimeState.WaitingForInput;i++)f.Runner.Step();Call(f,"RefreshRuntime");Check(Field<Form>(f,"turtleWindow")==null&&Field<Panel>(f,"inputPanel").Visible,"Input pause returns from drawing to input field");f.SetDocument(new Diagram(),null,false);
 }
 [STAThread]static int Main(){try{root=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"turtle-ui");Directory.CreateDirectory(root);Application.EnableVisualStyles();UiMotion.SetEnabled(true);Editors();RenderAndExport();CachedState();Exception failure=null;using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-3000);f.Shown+=delegate{f.BeginInvoke(new Action(delegate{try{MainUi(f);}catch(Exception ex){failure=ex;}finally{f.Close();}}));};Application.Run(f);}if(failure!=null)throw failure;Console.WriteLine("TURTLE_UI_PASS checks="+checks);return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
